mapper.select:
SELECT
log_id,user_id,operation_type,operation_target,target_id,permission_code,result,error_message,ip_address,operation_time
FROM sys_operation_log

    AND user_id=#{user}
    AND target_id=#{target}
    AND operation_type=#{query.operationType}
    AND operation_target=#{query.operationTarget}
    AND result=#{query.result}
    AND operation_time >= #{begin}
    AND operation_time < #{end}

ORDER BY operation_time DESC, log_id DESC
